/**
 * A dark hero band: the head row, a badge, a title with weighted words, the prompt box (or actions) and topic
 * pills.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Container } from "../primitives/container/container";
import { Stack } from "../primitives/stack/stack";
import { ActionGroup } from "../components/action-group";
import { HeroBadge } from "../components/hero-badge";
import { HeroHead } from "../components/hero-head";
import { PromptComposer } from "../components/prompt-composer";
import { TopicChips } from "../components/topic-chips";
import { WeightedTitle } from "../components/weighted-title";
import { defaults } from "../presets/defaults";
import { cn } from "../utils";
import type { HeroComposer, HeroNav } from "./hero-prompt.types";
import type { ActionSet } from "../components/cta-actions.types";
import type { NavLink } from "./nav-bar.types";
import type { Topic } from "../components/topic-chips.types";

export type HeroPromptProps = {
  title: string;
  level?: 1 | 2;
  badge?: string;
  badgeMark?: string;
  actions?: ActionSet;
  composer?: HeroComposer;
  nav?: HeroNav;
  topics?: Topic[];
  density?: "roomy" | "default" | "compact";
};

export function HeroPrompt({
  title,
  level = 1,
  badge,
  badgeMark,
  actions,
  composer,
  nav,
  topics,
  density = "roomy",
}: HeroPromptProps) {
  return (
    <Block
      tag="section"
      className={cn(
        "flex w-full flex-col bg-foreground text-background py-8 [&_.text-muted-foreground]:text-background/70",
        defaults.hero.band
      )}
      aria-labelledby="home-hero-title"
      data-testid="section"
      data-tone="inverse"
      data-density={density}
      data-chrome="nav"
    >
      <Container className={cn("mx-auto w-full px-8", defaults.hero.container)} data-slot="container">
        <Stack gap="0" align="stretch">
          <HeroHead
            brand={nav?.brand}
            links={nav?.links}
            current={nav?.current}
            login={nav?.login}
            loginHref={nav?.loginHref}
            skip={nav?.skip}
            navLabel={nav?.label}
            cta={actions?.cta}
            href={actions?.href}
          />
          <Stack
            gap="0"
            align="center"
            className={cn("mx-auto w-full pt-24 pb-16", defaults.hero.column)}
            data-testid="hero-column"
          >
            {badge ? (
              <HeroBadge label={badge} mark={badgeMark} />
            ) : null}
            <WeightedTitle id="home-hero-title" title={title} weights={defaults.hero.titleWeights} level={level} />
            {(actions?.mode === "form") ? (
              <PromptComposer
                label={actions?.emailLabel}
                attachLabel={composer?.attachLabel}
                modelLabel={composer?.modelLabel}
                send={actions?.cta}
                href={actions?.href}
              />
            ) : actions?.cta ? (
              <ActionGroup
                primary={actions?.cta}
                primaryHref={actions?.href}
                secondary={((actions?.mode === "two") ? actions?.secondary : undefined)}
                secondaryHref={actions?.secondaryHref}
                align={(true ? "center" : "start")}
              />
            ) : null}
            {topics ? (
              <TopicChips topics={topics} tone="inverse" />
            ) : null}
          </Stack>
        </Stack>
      </Container>
    </Block>
  );
}

