import type { NavLink } from "./nav-bar.types";

export type HeroComposer = {
  /** attachment chip label */
  attachLabel?: string;
  /** model pill label */
  modelLabel?: string;
};

export type HeroNav = {
  /** brand word of the head row */
  brand?: string;
  /** menu links of the head row */
  links?: NavLink[];
  /** id of the current link */
  current?: string;
  login?: string;
  loginHref?: string;
  /** skip link text */
  skip?: string;
  /** accessible name of the menu */
  label?: string;
};
